import type {
  DocNetIntegration,
  DocNetIntegrationCreate,
  DocNetIntegrationUpdate,
  DocNetIntegrationPlatform,
  DocNetIntegrationListResponse,
  DocNetConnectCodeResponse,
  DocNetLinkCodeResponse,
} from 'src/@types/docnet';
import DocNetBaseService from 'src/services/docnet/DocNetBaseService';
import { api } from 'src/pages/APIs';

export default class DocNetIntegrationService extends DocNetBaseService {
  public async getIntegrations(
    platform?: DocNetIntegrationPlatform,
  ): Promise<DocNetIntegration[]> {
    const headers = await this.getHeaders();
    const params = new URLSearchParams();
    if (platform) params.set('platform', platform);
    const qs = params.toString();
    const url = api.docnet_integrations + (qs ? `?${qs}` : '');
    const response = await super.get(url, { headers });
    if (response && typeof response === 'object' && 'items' in response) {
      return (response as DocNetIntegrationListResponse).items;
    }
    return Array.isArray(response) ? (response as DocNetIntegration[]) : [];
  }

  public async getIntegrationById(
    id: string,
  ): Promise<DocNetIntegration | undefined> {
    const headers = await this.getHeaders();
    try {
      return (await super.get(`${api.docnet_integrations}/${id}`, {
        headers,
      })) as DocNetIntegration;
    } catch {
      return undefined;
    }
  }

  public async generateTeamsConnectCode(): Promise<DocNetConnectCodeResponse> {
    const headers = await this.getHeaders();
    return (await super.post(
      `${api.docnet_integrations}/teams/connect-code`,
      {},
      { headers },
    )) as DocNetConnectCodeResponse;
  }

  public async generateTeamsLinkCode(): Promise<DocNetLinkCodeResponse> {
    const headers = await this.getHeaders();
    return (await super.post(
      `${api.docnet_integrations}/teams/link-code`,
      {},
      { headers },
    )) as DocNetLinkCodeResponse;
  }

  public async createIntegration(
    data: DocNetIntegrationCreate,
  ): Promise<DocNetIntegration> {
    const headers = await this.getHeaders();
    return (await super.post(api.docnet_integrations, data, {
      headers,
    })) as DocNetIntegration;
  }

  public async updateIntegration(
    id: string,
    data: DocNetIntegrationUpdate,
  ): Promise<DocNetIntegration> {
    const headers = await this.getHeaders();
    return (await super.put(`${api.docnet_integrations}/${id}`, data, {
      headers,
    })) as DocNetIntegration;
  }

  public async deleteIntegration(id: string): Promise<void> {
    const headers = await this.getHeaders();
    await super.delete(`${api.docnet_integrations}/${id}`, { headers });
  }

  public async toggleIntegration(
    id: string,
    isEnabled: boolean,
  ): Promise<DocNetIntegration> {
    const headers = await this.getHeaders();
    return (await super.post(
      `${api.docnet_integrations}/${id}/toggle`,
      { is_enabled: isEnabled },
      { headers },
    )) as DocNetIntegration;
  }
}
